import { useEffect, useState } from 'react'
import { useAuth } from '@/app/providers/AuthProvider'
import { useTenant } from '@/app/providers/TenantProvider'
import { tenantsService, type TenantSummary } from '@/integrations/supabase/tenants'
import { Building2, ChevronDown } from 'lucide-react'
import { useNavigate } from 'react-router-dom'

export function TenantSwitcher() {
  const { isSuperAdmin } = useAuth()
  const { activeSlug, setActiveSlug, manifest } = useTenant()
  const [open, setOpen] = useState(false)
  const [tenants, setTenants] = useState<TenantSummary[]>([])
  const navigate = useNavigate()

  useEffect(() => {
    if (isSuperAdmin && open && tenants.length === 0) {
      tenantsService.listAll().then(setTenants)
    }
  }, [isSuperAdmin, open, tenants.length])

  if (!isSuperAdmin) return null

  return (
    <div className="relative">
      <button
        onClick={() => setOpen((v) => !v)}
        className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted"
      >
        <Building2 size={12} />
        <span className="max-w-[120px] truncate">{manifest?.name ?? activeSlug}</span>
        <ChevronDown size={12} />
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div className="absolute right-0 mt-1 w-56 bg-surface border border-border rounded-lg shadow-lg z-50 py-1 max-h-80 overflow-y-auto">
            <div className="px-3 py-1.5 text-[10px] uppercase tracking-wide text-muted-foreground font-semibold">
              Switch tenant
            </div>
            {tenants.length === 0 ? (
              <div className="px-3 py-2 text-xs text-muted-foreground">Loading…</div>
            ) : (
              tenants.map((t) => (
                <button
                  key={t.id}
                  onClick={() => { setActiveSlug(t.slug); setOpen(false) }}
                  className={`w-full text-left px-3 py-1.5 text-xs hover:bg-muted flex items-center justify-between ${
                    t.slug === activeSlug ? 'text-accent font-medium' : ''
                  }`}
                >
                  <span className="truncate">{t.name}</span>
                  <span className="text-muted-foreground font-mono text-[10px]">{t.slug}</span>
                </button>
              ))
            )}
            <div className="border-t border-border mt-1 pt-1">
              <button
                onClick={() => { setOpen(false); navigate('/admin/tenants') }}
                className="w-full text-left px-3 py-1.5 text-xs hover:bg-muted text-muted-foreground"
              >
                Manage tenants →
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  )
}
